import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2018-JUN-06 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2018-JUN-06 :: Ceph Developer Monthly","date":"2018-06-06T00:00:00.000Z","updated":"2018-06-07T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","存储","CephFS","RBD","RGW","RESTful API","智能监控"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-JUN-06_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2018/2018-JUN-06_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),p={name:"posts/2018/2018-JUN-06_-_-_Ceph_Developer_Monthly.md"};function r(s,l,a,n,_,u){return t(),i("div",null,[...l[0]||(l[0]=[o("<p>本次会议主要讨论了Ceph项目的多个关键议题，包括性能优化、NFS集群化、REST API和Dashboard API开发、智能设备故障预测、智能故障报告、跨云文件系统等。</p><p><strong>一、Ceph-RBD性能优化</strong></p><ul><li>讨论了使用多个Tanglin进行独立操作，共享DPDK网络卡以提高性能。</li><li>使用RCU技术实现共享数据结构，提高并发访问效率。</li><li>优化日志记录和内存使用，减少性能开销。</li></ul><p><strong>二、NFS Ganesha集群化</strong></p><ul><li>讨论了使用Rados作为存储后端，实现NFS Ganesha的集群化。</li><li>引入“grace period”机制，防止节点重启后状态冲突。</li><li>使用Rados对象存储恢复数据库，实现节点故障恢复。</li></ul><p><strong>三、REST API &amp; Dashboard API</strong></p><ul><li>讨论了使用Swagger生成API文档，提高API的易用性。</li><li>引入角色和用户权限管理，提高安全性。</li><li>在Nautilus版本中正式推出REST API。</li></ul><p><strong>四、智能预测设备故障</strong></p><ul><li>收集SMART指标，预测设备故障。</li><li>使用外部服务进行设备故障预测。</li><li>实现设备故障自动化处理。</li></ul><p><strong>五、智能故障报告</strong></p><ul><li>在崩溃时生成崩溃目录报告。</li><li>将崩溃报告上传到Manager。</li><li>在Manager中存储崩溃报告。</li></ul><p><strong>六、跨云文件系统</strong></p><ul><li>使用快照和同步机制实现跨云数据备份。</li><li>使用版本控制技术实现跨云数据冲突解决。</li><li>将RGW作为访问外部存储的网关。</li></ul><p><strong>七、其他议题</strong></p><ul><li>讨论了CephFS的元数据复制、RGW的云同步功能、Ceph的日志记录和跟踪等议题。</li></ul><p><strong>后续行动计划</strong></p><ul><li>各项议题的负责人将根据会议讨论结果，制定详细的开发计划和时间表。</li><li>定期召开会议，跟踪项目进展。</li><li>鼓励社区成员参与项目开发。</li></ul>",17)])])}const d=e(p,[["render",r]]);export{h as __pageData,d as default};
